'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeRead=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}};
const persist=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{toast('Browser storage is unavailable or full. Keep this tab open and export important work.');}};
let serverState={configured:false,model:'gemini-3.5-flash-lite',cooldownSeconds:60,dailyLimit:20,dailyRequests:0,nextAt:0,busy:false,queued:0,message:'Connecting to the grading service…'},content,topicFilter='All',searchText='',busy=false,gradingController=null,currentResult=null,gradingError='',jobMessage='',activeJob=null;
let attempt=safeRead('ael-attempt',null),history=safeRead('ael-history',[]),sqlEvidence={},sqlBusy=new Set();
const main=$('#main');
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').hidden=true,4500);}
function saveAttempt(){if(attempt)persist('ael-attempt',attempt);}
async function refreshStatus(){
 try{const r=await fetch('api/status',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const data=await r.json();serverState={...data,nextAt:Date.now()+Math.max(0,data.nextAllowedAt-data.serverNow)};}
 catch{serverState={...serverState,configured:false,message:'The grading backend is not connected. Deploy this package as a Render Web Service; instant checks still work.'};}
 updateConnection();renderStatus();
}
function updateConnection(){const wait=Math.max(0,Math.ceil((serverState.nextAt-Date.now())/1000)),capped=serverState.dailyRequests>=serverState.dailyLimit;$('#api-badge').textContent=busy?'Grading in progress':!serverState.configured?'AI setup pending':capped?'Daily limit reached':wait?`Shared cooldown · ${wait}s`:'Gemini connected';$('#connection-text').textContent=serverState.configured?'Server grading ready':'Instant checks ready';$('#connection-dot').classList.toggle('on',!!serverState.configured);$$('.quota-live').forEach(el=>el.textContent=`Shared Gemini attempts: ${serverState.dailyRequests}/${serverState.dailyLimit} · ${serverState.queued||0} queued · ${wait?'Next request in '+wait+'s':'Ready'}`);$$('.grade-button').forEach(b=>{b.disabled=busy||!serverState.configured||capped||wait>0;b.textContent=busy?'Grading your attempt…':!serverState.configured?'AI setup pending':capped?'Shared daily limit reached':wait?`Gemini available in ${wait}s`:'Grade with Gemini →';});const message=$('#job-message');if(message)message.textContent=jobMessage||'Your submitted answers are being graded.';}
function renderStatus(){const el=$('#service-status');if(!el)return;const wait=Math.max(0,Math.ceil((serverState.nextAt-Date.now())/1000));el.innerHTML=`<div class="notice ${serverState.configured?'success':''}">${escapeHTML(serverState.message)}</div><div class="criterion"><span>Model</span><b>${escapeHTML(serverState.model)}</b></div><div class="criterion"><span>Shared request spacing</span><b>${serverState.cooldownSeconds} seconds</b></div><div class="criterion"><span>Gemini attempts this quota day</span><b>${serverState.dailyRequests} / ${serverState.dailyLimit}</b></div><div class="criterion"><span>Next request</span><b>${wait?wait+' seconds':'Ready'}</b></div><div class="criterion"><span>Waiting jobs</span><b>${serverState.queued||0}</b></div>`;}
function busyNotice(){return busy?'<div class="busy-banner" role="status"><span id="job-message">Your submitted answers are being graded.</span> You can browse while it finishes. <button class="link-button" data-action="cancel-grading">Cancel request</button></div>':'';}
function heading(kicker,title,sub){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p class="sub">${sub}</p></div><span class="date-chip">${new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span></div>`;}
function topicCard(icon,color,title,sub,n,topic){return `<a class="topic-card" href="#practice?topic=${encodeURIComponent(topic)}"><div class="topic-icon ${color}">${icon}</div><h3>${title}</h3><p>${sub}</p><div class="topic-foot"><span>${n} source-based questions</span><span>Start practising ↗</span></div></a>`;}
function overview(){const last=history[0];return heading('A LITTLE PRACTICE. A LOT MORE CONFIDENCE.','Make your preparation count.','Work through real course cases. Understand your mistakes. Walk in prepared.')+`<section class="hero"><div><span class="eyebrow">FROM PRACTICE TO PROGRESS</span><h2>Know more than<br>the right answer.</h2><p>Test your skills in Excel, SQL and regression — then see where your reasoning can improve.</p><a class="lime" href="#exam">Take a mock exam <span>↗</span></a></div><div class="grade-art" aria-label="Illustration of an explained practice grade"><div class="grade-card"><span>PRACTICE FEEDBACK</span><b>7<span style="font-size:15px;letter-spacing:0"> / 12</span></b><small>Illustrative Danish grade</small><div class="grade-bar"><i></i></div><small>See what takes you to the next level.</small></div><span class="art-tag">✓ Understand the why.</span></div></section><div class="stats"><div class="stat"><div class="stat-top">Ready to practise <span>▤</span></div><b>${content.questions.length}</b><small>Questions from your course cases</small></div><div class="stat"><div class="stat-top">Core skill areas <span>◫</span></div><b>4</b><small>Excel, SQL, payroll & regression</small></div><div class="stat"><div class="stat-top">Graded attempts <span>✓</span></div><b>${history.length}</b><small>Saved on this browser</small></div><div class="stat"><div class="stat-top">Latest practice grade <span>↗</span></div><b>${last?.complete?escapeHTML(last.grade):'—'}</b><small>${last?last.complete?'Indicative, explained assessment':'Partial assessment · see results':'Your starting point is ahead'}</small></div></div><div class="section-heading"><h2>Choose your focus.</h2><a href="#practice">View all questions ↗</a></div><div class="topics">${topicCard('ƒx','','Excel & ETL','Clean, transform and connect data with reusable methods.',8,'Excel & ETL')}${topicCard('⌘','blue','SQL queries','Turn a business question into the right database result.',18,'SQL')}${topicCard('↗','peach','Regression & interpretation','Make predictions. Explain relationships and uncertainty.',7,'Regression')}</div><div class="bottom-note"><span style="font-size:24px">◉</span><div><b>A grade that gives you somewhere to go.</b><p>Get criterion-by-criterion feedback and a specific next step. Instant SQL checks work without an API key.</p></div></div>`;}
function bank(){const topics=['All','Excel & ETL','SQL','Payroll & audit','Regression'];const shown=content.questions.filter(q=>(topicFilter==='All'||q.topic===topicFilter)&&`${q.title} ${q.id} ${q.prompt}`.toLowerCase().includes(searchText.toLowerCase()));return heading('BUILD ONE SKILL AT A TIME','Your question bank.','Choose an exercise, work independently, then check your answer.')+`<div class="filters">${topics.map(t=>`<button class="chip ${t===topicFilter?'selected':''}" data-topic="${t}">${t}</button>`).join('')}</div><input class="search" id="search" aria-label="Search questions" placeholder="Search a question or skill…" value="${escapeHTML(searchText)}"><p class="small">${shown.length} questions · Adapted from the supplied materials; not a copy of the teacher’s exam bank.</p><div class="card">${shown.map(q=>`<div class="question-row"><span class="tag">${q.id}</span><div class="row-content"><span class="eyebrow">${q.topic}</span><h3>${q.title}</h3><p>${q.kind==='sql'?'Run and check SQL in your browser':q.kind==='number'?'Instant numerical check':'Written answer · Gemini feedback'} · ${q.minutes} min suggested</p></div><button class="secondary" data-open="${q.id}">Practise ↗</button></div>`).join('')||'<p>No matching questions. Try another search.</p>'}</div>`;}
function exam(){return heading('A REHEARSAL FOR THE REAL THING','Put it all together.','Choose a format. Complete the attempt before revealing answers or feedback.')+`<div class="exam-options"><button class="exam-option" data-exam="manipulation"><span class="tag">8 MINUTES · 5 QUESTIONS</span><h3>Data manipulation</h3><p>Three Excel & ETL questions and two SQL queries. Use the supplied files or the built-in SQL checker after submission.</p><strong>Start manipulation exam ↗</strong></button><button class="exam-option" data-exam="interpretation"><span class="tag">5 MINUTES · 4 QUESTIONS</span><h3>Data interpretation</h3><p>A restaurant regression case: predict, interpret coefficients and explain what the model can tell you.</p><strong>Start interpretation exam ↗</strong></button><button class="exam-option" data-exam="full"><span class="tag">13 MINUTES · 8 QUESTIONS</span><h3>Mixed practice</h3><p>Two Excel tasks, two SQL queries, a payroll or audit question, and three regression exercises.</p><strong>Start mixed exam ↗</strong></button></div><div class="card"><h2>A fairer way to practise.</h2><div class="steps"><div><span class="tag">01 · WORK INDEPENDENTLY</span><p>The timer is a pacing tool. When it expires, finish and submit manually; late submissions are labelled.</p></div><div><span class="tag">02 · SHOW YOUR WORK</span><p>Write formulas, SQL or explanations. A correct method can earn partial credit even if the final answer is wrong.</p></div><div><span class="tag">03 · LEARN FROM THE GAP</span><p>Read the marking guide, check the explanation and retry a weak skill with a new question.</p></div></div></div>${attempt?`<div class="notice">You have a saved ${attempt.submitted?'submitted':'unfinished'} attempt. <a href="#work">Return to it →</a></div>`:''}`;}
function shuffle(arr){return arr.map(v=>({v,n:Math.random()})).sort((a,b)=>a.n-b.n).map(x=>x.v);}
function startAttempt(ids,label,seconds,mode){attempt={uid:crypto.randomUUID(),ids,label,seconds,remaining:seconds,running:false,deadline:null,index:0,answers:{},mode,submitted:false,createdAt:new Date().toISOString(),expired:false};sqlEvidence={};saveAttempt();location.hash='work';render();}
function newExam(type){if(busy){toast('Let the current grading request finish first.');return;}if(attempt&&!attempt.submitted&&Object.values(attempt.answers).some(x=>x.trim())&&!confirm('Starting a new attempt replaces your unfinished draft. Continue?'))return;
 const pick=(topic,n)=>shuffle(content.questions.filter(q=>q.topic===topic)).slice(0,n).map(q=>q.id);
 const ids=type==='manipulation'?[...pick('Excel & ETL',3),...pick('SQL',2)]:type==='interpretation'?['R01','R02','R03','R04']:[...pick('Excel & ETL',2),...pick('SQL',2),...pick('Payroll & audit',1),...pick('Regression',3)];startAttempt(ids,type==='full'?'Mixed practice exam':type==='manipulation'?'Data manipulation exam':'Data interpretation exam',type==='full'?780:type==='manipulation'?480:300,'exam');}
function questionById(id){return content.questions.find(q=>q.id===id);}
function modelHTML(q){if(!q.model)return '';const m=content.models.find(x=>x.id===q.model);return `<details open><summary>Regression output · ${m.id} model</summary><p class="small">Outcome: ${m.outcome} · n=${m.n} · R²=${m.r2.toFixed(4)}</p><div class="table-wrap"><table class="model-table"><thead><tr><th>Term</th><th>Estimate</th><th>Std. error</th><th>p-value</th></tr></thead><tbody>${m.terms.map(t=>`<tr><td>${t.term}</td><td>${t.estimate.toFixed(6)}</td><td>${t.se.toFixed(6)}</td><td>${t.p<.0001?'&lt;0.0001':t.p.toFixed(4)}</td></tr>`).join('')}</tbody></table></div><p class="small">${m.notes}</p></details>`;}
function questionFiles(q){let keys=q.dataset?[q.dataset]:[];if(q.topic==='Payroll & audit'&&q.id.startsWith('P'))keys=[...new Set([...keys,'pay2015','pay2016','jobs','locations'])];if(q.topic==='Regression')keys=['restaurant','restaurant_daily'];if(q.id.startsWith('A'))keys=['pcard_instructions'];return keys;}
function downloadHTML(key){const f=content.files[key];return f?`<a href="${f.path}" download="${f.name}" class="small">↓ ${escapeHTML(f.name)}</a>`:'';}
function work(){if(!attempt)return `<div class="empty"><h2>Your next attempt is waiting.</h2><a class="primary" href="#exam">Choose an exam →</a></div>`;const q=questionById(attempt.ids[attempt.index]);if(!q)return '<p>This saved question is no longer available. Start a new exam.</p>';const canCheck=attempt.mode==='practice'||attempt.submitted;const evidence=sqlEvidence[q.id];return heading(attempt.mode==='exam'?'EXAM MODE · ANSWER FIRST':`FOCUSED PRACTICE · ${q.topic.toUpperCase()}`,attempt.label,`${attempt.mode==='exam'?'Feedback unlocks after submission.':'Explore the marking guide whenever you’re ready.'} Answers save locally as you type.`)+`<div class="work-layout"><div><div class="card"><span class="tag">${q.id} · ${q.topic} · 10 MARKS</span><h2 class="question-title">${q.title}</h2><p class="prompt">${escapeHTML(q.prompt)}</p>${modelHTML(q)}<label for="answer">${q.kind==='sql'?'Your SQL query':q.kind==='number'?'Your numerical answer':'Your answer and reasoning'}</label><textarea id="answer" maxlength="3500" class="${q.kind==='sql'?'code':''}" placeholder="${q.kind==='sql'?'SELECT …':q.kind==='number'?'Enter a number only; use a dot or comma for decimals.':'Show your method and explain the result…'}" ${busy?'readonly':''}>${escapeHTML(attempt.answers[q.id]||'')}</textarea><div class="button-row" style="margin-top:16px">${canCheck&&q.kind!=='text'?`<button class="secondary" data-action="check" ${sqlBusy.has(q.id)?'disabled':''}>${q.kind==='sql'?'Run & check SQL':'Check number'} ↗</button>`:''}${attempt.index>0?'<button class="secondary" data-action="previous">← Previous</button>':''}${attempt.index<attempt.ids.length-1?'<button class="primary" data-action="next">Next question →</button>':''}</div><div id="check-feedback" aria-live="polite">${evidence?evidenceHTML(evidence):''}</div><p class="source">Source: ${escapeHTML(q.source)}. Practice adaptation.</p>${q.kind==='sql'?`<details><summary>Database schema</summary><pre>${escapeHTML(content.schemas[q.dataset])}</pre></details>`:''}${canCheck?`<details><summary>Show reference answer & marking guide</summary><pre>${escapeHTML(q.answer)}</pre>${q.criteria.map(c=>`<div class="criterion"><span>${c.label}</span><b>${c.max} marks</b></div>`).join('')}<p class="small">Alternative correct methods are accepted. If you reveal the answer, treat this as learning practice rather than an independent readiness test.</p></details>`:''}</div><div class="card"><h3>Files for this question</h3><div style="display:grid;gap:12px">${questionFiles(q).map(downloadHTML).join('')||'<p class="small">This question is self-contained.</p>'}</div></div></div><aside class="work-sidebar"><div class="sticky"><div class="card"><span class="eyebrow">${attempt.mode==='exam'?'EXAM TIMER':'PRACTICE TIMER'}</span><div class="timer" id="exam-clock" role="timer" aria-label="Time remaining">${clock(remaining())}</div><div class="timer-controls"><button class="secondary" data-action="timer">${attempt.running?'Pause':attempt.expired?'Expired':'Start'}</button><button class="secondary" data-action="reset-timer">Reset</button></div><p class="small" id="timer-status">${attempt.expired?'Time expired. You can still submit.':'Start after downloading your files.'}</p></div><div class="card"><span class="eyebrow">YOUR ATTEMPT</span><div class="question-nav">${attempt.ids.map((id,i)=>`<button aria-label="Question ${i+1}: ${escapeHTML(questionById(id).title)}" class="qnum ${i===attempt.index?'current':''} ${attempt.answers[id]?.trim()?'answered':''}" data-qindex="${i}">${i+1}</button>`).join('')}</div><p class="small" id="answered-count">${attempt.ids.filter(id=>attempt.answers[id]?.trim()).length} of ${attempt.ids.length} answered</p>${!attempt.submitted?'<button class="primary" style="width:100%" data-action="submit">Submit attempt →</button>':'<p class="small">Submitted. You can revise your work and grade again.</p>'}${attempt.submitted||attempt.mode==='practice'?`<button class="primary grade-button" style="width:100%;margin-top:10px" data-action="grade">Grade with Gemini →</button><button class="secondary" style="width:100%;margin-top:10px" data-action="instant-grade">Instant checks only</button><p class="quota-line quota-live"></p>`:''}</div></div></aside></div>`;}
function clock(s){s=Math.max(0,Math.ceil(s));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
function remaining(){if(!attempt)return 0;return attempt.running?Math.max(0,(attempt.deadline-Date.now())/1000):attempt.remaining;}
function tick(){updateConnection();if(!attempt)return;let r=remaining();if(attempt.running&&r<=0){attempt.running=false;attempt.remaining=0;attempt.expired=true;saveAttempt();toast('Time is up. Finish and submit your attempt when ready.');}const el=$('#exam-clock');if(el){el.textContent=clock(r);el.classList.toggle('expired',attempt.expired);if(attempt.expired){$('#timer-status').textContent='Time expired. You can still submit.';const b=$('[data-action="timer"]');if(b)b.textContent='Expired';}}}
function evidenceHTML(e){if(!e.ok)return `<div class="notice error">${escapeHTML(e.error)}</div>`;return `<div class="notice ${e.match?'success':'error'}">${e.match?'✓ Matches the reference result.':'The result differs from the reference.'} ${e.rowCount!==undefined?`${e.rowCount} row(s) returned.`:''}</div>${e.preview?.length?`<div class="table-wrap"><table><thead><tr>${e.columns.map(c=>`<th>${escapeHTML(c)}</th>`).join('')}</tr></thead><tbody>${e.preview.map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v===null?'NULL':v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small">Showing up to eight rows. Result equivalence is checked on this database, not on unseen data.</p>`:''}`;}
function runSql(q,answer){return new Promise(resolve=>{const worker=new Worker('sql-worker.js');const timeout=setTimeout(()=>{worker.terminate();resolve({ok:false,error:'Query stopped after 8 seconds. Simplify the query and try again.'});},8000);worker.onmessage=({data})=>{clearTimeout(timeout);worker.terminate();resolve(data);};worker.onerror=()=>{clearTimeout(timeout);worker.terminate();resolve({ok:false,error:'SQL engine could not load. Serve this site over HTTPS or localhost and check that vendor files are present.'});};worker.postMessage({path:content.files[q.dataset].path,query:answer,reference:q.sql,ordered:q.ordered});});}
async function check(q,answer){if(!answer.trim())return {ok:false,error:'Enter an answer first.'};if(q.kind==='number'){const v=ExamCore.parseNumber(answer);if(!Number.isFinite(v))return {ok:false,error:'Enter a number only, with no currency symbol or thousands separator.'};return {ok:true,match:Math.abs(v-q.value)<=q.tolerance};}return runSql(q,answer);}
async function checkCurrent(){const uid=attempt.uid,q=questionById(attempt.ids[attempt.index]),a=attempt.answers[q.id]||'';if(sqlBusy.has(q.id))return;sqlBusy.add(q.id);render();const result=await check(q,a);sqlBusy.delete(q.id);if(attempt.uid===uid&&attempt.answers[q.id]===a){sqlEvidence[q.id]=result;render();}}
function materialPage(){return heading('THE SOURCE OF YOUR PRACTICE','Keep the evidence close.','Download original course datasets and instructions. All exercises stay within these cases.')+`<div class="card">${Object.entries(content.files).map(([key,f])=>`<div class="material-row"><div><span class="tag">${key.replaceAll('_',' ')}</span><p>${escapeHTML(f.name)}</p><span class="small">${f.bytes>1048576?(f.bytes/1048576).toFixed(1)+' MB':Math.ceil(f.bytes/1024)+' KB'}</span></div><a class="secondary" href="${f.path}" download="${f.name}">Download ↓</a></div>`).join('')}</div><div class="note">SQL practice uses the original songs and Chinook databases. Movies and the optional Fiftyville mystery are not included in this first question bank. P-card exercises use the policy instructions and self-contained scenarios; the full P-card database is not needed. Restaurant output is calculated from the supplied workbook, with the daily analysis file available above.</div>`;}
function rubricPage(){return `<details><summary>How the practice grade is calculated</summary><p>Each question has 10 marks and a published marking guide. Gemini awards marks per criterion; this app validates the scores and calculates the grade. Exact result checks override AI scores when the answer is demonstrably correct.</p><div class="table-wrap"><table><thead><tr><th>Mark percentage</th><th>Practice grade</th></tr></thead><tbody>${[['90–100%','12'],['75–<90%','10'],['60–<75%','7'],['45–<60%','4'],['30–<45%','02'],['>0–<30%','00'],['0%','−3']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table></div><p class="small">These thresholds are an illustrative practice convention created for this app, not official Danish percentage boundaries or the teacher’s grading rubric. An oral exam assesses broader performance and understanding. A zero on this exercise set does not establish an official −3 performance. AI feedback can be wrong; compare it with the marking guide and sources.</p></details>`;}
function resultHTML(r){return `<div class="card"><div class="score-header"><div class="big-grade">${r.complete?escapeHTML(r.grade):'—'}</div><div><span class="eyebrow">${r.complete?'INDICATIVE DANISH PRACTICE GRADE':'PARTIAL ASSESSMENT'}</span><h2>${r.label}</h2><p class="sub">${r.total}/${r.assessedMax} assessed marks · ${r.assessedCount}/${r.items.length} questions assessed</p><p class="small">${escapeHTML(r.method)} · ${new Date(r.at).toLocaleString('en-GB')} ${r.late?'· Submitted after time expired':''}</p></div></div><p>${escapeHTML(r.summary)}</p>${!r.complete?'<div class="note">No whole-attempt grade is shown because some questions need written-answer assessment. Use Gemini for full feedback.</div>':''}${r.items.map(item=>{const q=questionById(item.id);return `<div class="feedback-card"><h3><span>${item.id} · ${q.title}</span><span class="inline-score">${item.assessed?item.score+'/10':'Unassessed'}</span></h3><p>${escapeHTML(item.feedback)}</p>${item.assessed?q.criteria.map((c,i)=>`<div class="criterion"><span>${escapeHTML(c.label)}</span><b>${item.marks[i]}/${c.max}</b></div>`).join(''):''}<div class="notice"><strong>Next step:</strong> ${escapeHTML(item.nextStep)}</div><details><summary>Your submitted answer & reference</summary><p class="small">Your submission</p><pre>${escapeHTML(r.answers[item.id]||'(blank)')}</pre><p class="small">Reference answer</p><pre>${escapeHTML(q.answer)}</pre></details><button class="link-button" data-open="${item.id}">Practise this skill again ↗</button></div>`;}).join('')}${rubricPage()}<div class="feedback-actions"><button class="secondary" data-export="${r.uid}">Export feedback ↓</button><button class="secondary" data-action="print">Print / save PDF</button><a class="primary" href="#exam">Try another exam →</a></div></div>`;}
function resultsPage(){return heading('TURN FEEDBACK INTO A NEXT STEP','Your progress, explained.','Results and submitted answers stay on this browser. Export anything you want to keep.')+(currentResult?resultHTML(currentResult):history.length?resultHTML(history[0]):'<div class="card empty"><span style="font-size:40px">↗</span><h2>Every attempt is a starting point.</h2><p>Complete a question or mock exam to see your first assessment here.</p><a class="primary" href="#exam">Choose a mock exam →</a></div>')+(history.length?`<div class="card"><div class="section-heading"><h3>Previous attempts</h3><button class="link-button" data-action="clear-history">Clear local history</button></div>${history.map(r=>`<div class="question-row"><div class="row-content"><h3>${escapeHTML(r.label)}</h3><p>${new Date(r.at).toLocaleString('en-GB')} · ${r.assessedCount}/${r.items.length} assessed</p></div><span class="inline-score">${r.complete?escapeHTML(r.grade):'Partial'}</span><button class="secondary" data-result="${r.uid}">View</button></div>`).join('')}</div>`:'');}
function route(){const [page,query]=(location.hash.slice(1)||'overview').split('?');return {page,params:new URLSearchParams(query)};}
function render(){if(!content)return;const {page}=route();$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(page==='work'?(attempt?.mode==='exam'?'exam':'practice'):page)));main.innerHTML=(gradingError?`<div class="notice error" role="alert">${escapeHTML(gradingError)}</div>`:'')+busyNotice()+({overview,practice:bank,exam,work,results:resultsPage,materials:materialPage}[page]||overview)();updateConnection();tick();}
function openSettings(){renderStatus();$('#settings').showModal();refreshStatus();}
function stopTimer(){if(attempt.running){attempt.remaining=remaining();attempt.running=false;attempt.deadline=null;saveAttempt();}}
async function submitAttempt(){if(busy)return;stopTimer();attempt.submitted=true;attempt.submittedAt=new Date().toISOString();saveAttempt();render();toast('Attempt submitted. Choose Gemini grading or instant checks.');}
function assembleResult(snapshot,items,method,summary){const assessed=items.filter(i=>i.assessed),total=assessed.reduce((s,i)=>s+i.score,0),assessedMax=assessed.length*10,complete=assessed.length===items.length;return {uid:crypto.randomUUID(),at:new Date().toISOString(),label:snapshot.label,answers:snapshot.answers,late:snapshot.expired,items,total,assessedMax,assessedCount:assessed.length,complete,grade:complete?ExamCore.grade(total/assessedMax*100):null,method,summary,contentVersion:content.version,rubricVersion:'practice-1'};}
function saveResult(r){currentResult=r;history=[r,...history].slice(0,30);persist('ael-history',history);location.hash='results';render();}
async function collectEvidence(snapshot){const evidence={};for(const id of snapshot.ids){const q=questionById(id);if(q.kind!=='text')evidence[id]=await check(q,snapshot.answers[id]||'');}return evidence;}
async function instantGrade(){if(busy)return;busy=true;render();const snapshot=structuredClone(attempt);try{const ev=await collectEvidence(snapshot);const items=snapshot.ids.map(id=>{const q=questionById(id),e=ev[id];const blank=!(snapshot.answers[id]||'').trim(),assessed=blank||(e?.ok===true);return {id,assessed,score:blank?0:e?.match?10:0,marks:q.criteria.map(c=>e?.match?c.max:0),feedback:blank?'No answer was submitted.':q.kind==='text'?'Written reasoning needs Gemini or manual assessment.':!e?.ok?e.error:e.match?'Your answer matches the reference result.':'Your result differs from the reference. An instant check cannot award method credit.',nextStep:e?.match?'Explain why your method works and test it on another question.':'Compare your approach with the reference answer. Use Gemini for method feedback and partial credit.'};});saveResult(assembleResult(snapshot,items,'Instant checks · no AI request','Numerical answers and SQL results were checked locally. Written answers remain unassessed; incorrect results receive no automatic method credit.'));}finally{busy=false;render();}}
async function geminiGrade(){
 if(busy)return;gradingError='';
 if(!serverState.configured){openSettings();return;}
 const snapshot=structuredClone(attempt),questions=snapshot.ids.map(questionById);busy=true;jobMessage='Sending your attempt to the grading service…';gradingController=new AbortController();render();
 const controller=gradingController;
 try{
  const submitted=await fetch('api/grade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:snapshot.ids,answers:snapshot.answers}),signal:controller.signal});
  let response;try{response=await submitted.json();}catch{throw Error('The grading service did not return a usable response. Your answers are preserved.');}
  if(!submitted.ok)throw Error(response.error?.message||'The grading request could not be accepted. Try again later.');
  activeJob={id:response.jobId,token:response.jobToken};let polls=0;
  while(!['complete','failed','cancelled'].includes(response.status)){
   if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');
   const wait=Math.max(0,Math.ceil((response.nextAllowedAt-response.serverNow)/1000));jobMessage=response.message+(response.status==='queued'?` Queue position: ${response.position||1}.${wait?' Next request in '+wait+'s.':''}`:'');updateConnection();
   await waitAbortable(2000,controller.signal);
   const polled=await fetch(`api/grade/${encodeURIComponent(activeJob.id)}`,{headers:{'X-Job-Token':activeJob.token},cache:'no-store',signal:controller.signal});try{response=await polled.json();}catch{throw Error('The grading service connection was interrupted. Your answers are preserved.');}if(!polled.ok)throw Error(response.error?.message||'The grading job is unavailable. Your answers are preserved.');
   if(++polls%5===0)refreshStatus();
   if(polls>600)throw Error('The grading job waited longer than 20 minutes. Your answers are preserved; try again later.');
  }
  if(response.status==='failed')throw Error(response.error?.message||'Grading failed. Your answers are preserved.');if(response.status==='cancelled')throw new DOMException('Cancelled','AbortError');
  const feedback=ExamCore.validateFeedback(response.feedback,questions),ev=response.evidence||{};
  const items=questions.map(q=>{const r=feedback.questions.find(x=>x.id===q.id),blank=!(snapshot.answers[q.id]||'').trim();const marks=blank?q.criteria.map(()=>0):r.marks;return {id:q.id,assessed:true,marks,score:marks.reduce((a,b)=>a+b,0),feedback:blank?'No answer was submitted.':r.feedback,nextStep:r.nextStep};});
  const method=feedback.summary.includes('No Gemini request was needed')?'Server-verified result checks':`Gemini ${response.model} + server-verified result checks`;
  saveResult(assembleResult(snapshot,items,method,feedback.summary));
 }catch(e){gradingError=e.name==='AbortError'?'Grading cancelled. Your answers are preserved.':e.message;toast(gradingError);}
 finally{if(controller.signal.aborted&&activeJob){fetch(`api/grade/${encodeURIComponent(activeJob.id)}`,{method:'DELETE',headers:{'X-Job-Token':activeJob.token},keepalive:true}).catch(()=>{});}activeJob=null;busy=false;gradingController=null;jobMessage='';render();refreshStatus();}
}
function waitAbortable(ms,signal){return new Promise((resolve,reject)=>{const abort=()=>{clearTimeout(timer);reject(new DOMException('Cancelled','AbortError'));};const timer=setTimeout(()=>{signal.removeEventListener('abort',abort);resolve();},ms);signal.addEventListener('abort',abort,{once:true});if(signal.aborted)abort();});}
function exportResult(id){const r=history.find(x=>x.uid===id)||currentResult;if(!r)return;const blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`exam-feedback-${r.at.slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function inputAnswer(e){if(e.target.id!=='answer'||busy||!attempt)return;const id=attempt.ids[attempt.index];attempt.answers[id]=e.target.value;delete sqlEvidence[id];saveAttempt();$('#answered-count').textContent=`${attempt.ids.filter(i=>attempt.answers[i]?.trim()).length} of ${attempt.ids.length} answered`;$$('[data-qindex]').forEach((b,i)=>b.classList.toggle('answered',!!attempt.answers[attempt.ids[i]]?.trim()));$('#check-feedback').innerHTML='';}
main.addEventListener('input',e=>{inputAnswer(e);if(e.target.id==='search'){const pos=e.target.selectionStart;searchText=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
main.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.topic){topicFilter=b.dataset.topic;render();return;}if(b.dataset.open){if(busy){toast('Finish the current assessment before starting another attempt.');return;}if(attempt&&!attempt.submitted&&Object.values(attempt.answers).some(a=>a.trim())&&!confirm('Replace the current unfinished draft?'))return;const q=questionById(b.dataset.open);startAttempt([q.id],q.title,q.minutes*60,'practice');return;}if(b.dataset.exam){newExam(b.dataset.exam);return;}if(b.dataset.qindex!==undefined){attempt.index=Number(b.dataset.qindex);saveAttempt();render();return;}if(b.dataset.result){currentResult=history.find(r=>r.uid===b.dataset.result);render();return;}if(b.dataset.export){exportResult(b.dataset.export);return;}
 switch(b.dataset.action){case 'next':attempt.index++;saveAttempt();render();break;case 'previous':attempt.index--;saveAttempt();render();break;case 'timer':if(attempt.expired)break;if(attempt.running)stopTimer();else{attempt.running=true;attempt.deadline=Date.now()+attempt.remaining*1000;saveAttempt();}render();break;case 'reset-timer':attempt.running=false;attempt.deadline=null;attempt.remaining=attempt.seconds;attempt.expired=false;saveAttempt();render();break;case 'submit':await submitAttempt();break;case 'check':await checkCurrent();break;case 'grade':await geminiGrade();break;case 'instant-grade':await instantGrade();break;case 'cancel-grading':gradingController?.abort();break;case 'print':window.print();break;case 'clear-history':if(confirm('Clear saved results from this browser?')){history=[];currentResult=null;persist('ael-history',[]);render();}break;}
});
$$('.settings-open').forEach(b=>b.addEventListener('click',openSettings));$('.close-settings').addEventListener('click',()=>$('#settings').close());$('#refresh-service').addEventListener('click',refreshStatus);
window.addEventListener('hashchange',()=>{const r=route();if(r.page==='practice'){const t=r.params.get('topic');if(t)topicFilter=t;}render();});window.addEventListener('storage',updateConnection);window.addEventListener('pagehide',saveAttempt);
(async()=>{try{const response=await fetch('content.json');if(!response.ok)throw Error();content=await response.json();if(attempt?.ids.some(id=>!questionById(id)))attempt=null;const t=route().params.get('topic');if(t)topicFilter=t;render();refreshStatus();setInterval(tick,1000);setInterval(refreshStatus,15000);}catch{main.innerHTML='<div class="notice error">The question bank could not load. Refresh the page, or check that content.json was uploaded alongside index.html.</div>';}})();
